export const personaByUsername = (u: string) => PERSONAS.find((p) => p.username === u);

/** Deterministic UUID (v4 layout) from a label, so the same persona has the same id on every deployment. */
export function stableUuid(label: string): string {
  const h = createHash('sha256').update(`fposetu:${label}`).digest('hex');
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-4${h.slice(13, 16)}-a${h.slice(17, 20)}-${h.slice(20, 32)}`;
}

export const sessionUserOf = (p: Persona, portal: Portal): SessionUser => ({ id: stableUuid(p.username), username: p.username, role: p.role, org: p.org, displayName: p.displayName, portal });

